(() => {
 const root=document.documentElement, themes=[['light','☀ 亮色'],['dark','☾ 暗色'],['eye-care','♧ 护眼'],['high-contrast','◧ 高对比']], accents=[['blue','靛蓝'],['green','绿色'],['orange','橙色'],['purple','紫色'],['rose','玫瑰']];
 const close=()=>document.querySelectorAll('.theme-menu,.user-menu').forEach(x=>x.classList.remove('open'));
 const toast=(message='已保存原型状态')=>{let el=document.querySelector('.toast');if(!el){el=document.createElement('div');el.className='toast';document.body.append(el)}el.textContent=message;el.classList.add('show');window.setTimeout(()=>el.classList.remove('show'),1800)};
 const theme=localStorage.getItem('theme')||'light',accent=localStorage.getItem('accent')||'';root.dataset.theme=theme;if(accent)root.dataset.accent=accent;
 document.querySelectorAll('[data-theme-toggle]').forEach(button=>{const menu=document.createElement('div');menu.className='theme-menu';menu.setAttribute('role','menu');menu.innerHTML=themes.map(([id,label])=>`<button type="button" data-theme="${id}">${label}</button>`).join('')+'<hr>'+accents.map(([id,label])=>`<button type="button" data-accent="${id}">● ${label}</button>`).join('');button.parentElement.append(menu);button.addEventListener('click',event=>{event.stopPropagation();close();menu.classList.add('open')});menu.addEventListener('click',event=>{const target=event.target.closest('button');if(!target)return;if(target.dataset.theme){root.dataset.theme=target.dataset.theme;localStorage.setItem('theme',target.dataset.theme);toast('已切换至 '+target.textContent.trim())}if(target.dataset.accent){root.dataset.accent=target.dataset.accent;localStorage.setItem('accent',target.dataset.accent);toast('强调色已更新')}close()})});
 document.querySelectorAll('.top-actions .avatar.mini').forEach(avatar=>{avatar.setAttribute('role','button');avatar.setAttribute('tabindex','0');avatar.setAttribute('aria-label','打开用户菜单');const menu=document.createElement('nav');menu.className='user-menu';menu.innerHTML='<a href="profile.html">我的主页</a><a href="user-center.html">用户中心</a><a href="#" data-toast="通知中心已打开">通知</a><a href="#" data-toast="已退出原型登录态">退出登录</a>';avatar.parentElement.append(menu);const toggle=e=>{e.stopPropagation();close();menu.classList.add('open')};avatar.addEventListener('click',toggle);avatar.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();toggle(e)}})});
 document.querySelectorAll('.top-actions').forEach(actions=>{const search=document.createElement('button');search.className='icon-btn';search.type='button';search.title='搜索';search.textContent='⌕';search.dataset.toast='搜索面板已打开';const notice=document.createElement('button');notice.className='icon-btn';notice.type='button';notice.title='通知';notice.textContent='◌';notice.dataset.toast='你有 3 条未读通知';const themeButton=actions.querySelector('[data-theme-toggle]');actions.insertBefore(search,themeButton);actions.insertBefore(notice,themeButton)});
 document.addEventListener('click',close);document.querySelectorAll('[data-toast]').forEach(button=>button.addEventListener('click',()=>toast(button.dataset.toast)));document.querySelectorAll('[data-like]').forEach(button=>button.addEventListener('click',()=>{button.classList.toggle('liked');const n=button.querySelector('span');if(n)n.textContent=Number(n.textContent)+(button.classList.contains('liked')?1:-1)}));document.querySelectorAll('[data-tab]').forEach(button=>button.addEventListener('click',()=>{button.parentElement.querySelectorAll('button').forEach(x=>x.classList.remove('active'));button.classList.add('active');toast('已切换至「'+button.textContent.trim()+'」视图')}));
 document.querySelectorAll('.admin-nav a').forEach(link=>{if(link.textContent.includes('帖子管理'))link.href='admin-posts.html';if(link.textContent.includes('仪表盘'))link.href='admin.html'});
})();
